def gen(rng):
    LIM = 2 ** 31
    OPS = '+-*/'

    def tdiv(a, b):
        q = abs(a) // abs(b)
        return q if (a < 0) == (b < 0) else -q

    def build(depth, lit):
        if depth == 0 or rng.random() < 0.25:
            v = rng.randint(0, lit)
            return ('n', v), v
        for _ in range(6):
            op = rng.choice(OPS)
            ln, lv = build(depth - 1, lit)
            rn, rv = build(depth - 1, lit)
            if op == '/':
                if rv == 0:
                    continue
                v = tdiv(lv, rv)
            elif op == '+':
                v = lv + rv
            elif op == '-':
                v = lv - rv
            else:
                v = lv * rv
            if -LIM <= v < LIM:
                return ('b', op, ln, rn), v
        v = rng.randint(0, lit)
        return ('n', v), v

    def render(nd, spaces):
        if nd[0] == 'n':
            return str(nd[1]), 3
        op = nd[1]
        ls, lp = render(nd[2], spaces)
        rs, rp = render(nd[3], spaces)
        p = 1 if op in '+-' else 2
        if lp < p or rng.random() < 0.1:
            ls = '(' + ls + ')'
        if rp <= p or rng.random() < 0.1:
            rs = '(' + rs + ')'
        sp = ' ' if spaces and rng.random() < 0.7 else ''
        return ls + sp + op + sp + rs, p

    def rand_expr(depth, lit, spaces=True):
        nd, _ = build(depth, lit)
        s, _ = render(nd, spaces)
        return s

    tests = ['7', ' 7 ', '0', '(((5)))', '2147483647', '2147483647 - 2147483647 + 1', '10 - 2 - 3', '100/10/5', '2*3/4', '7 / 2 * 2',
             '1 - 9 / 2', '(1-9)/2', '(0-7)/2', '(0 - 7) * (0 - 3)', '1-(2-(3-(4-5)))', '8 - 3 * (2 + 5) / 4', '(1 - 9) / 3', ' 42 ',
             '2147483647/2147483647', '(0-2147483647)/2', '6/(0-4)', '(0-6)/(0-4)', '0*5+0/3']
    for _ in range(40):
        s = rand_expr(rng.randint(1, 4), rng.choice([9, 20, 1000, 100000]), rng.random() < 0.7)
        if len(s) < 380:
            tests.append(s)
    for _ in range(10):
        s = rand_expr(rng.randint(5, 7), rng.choice([9, 99]))
        tests.append(s)

    # long sums of small products and quotients
    def long_terms(target):
        parts = []
        total = 0
        while total < target:
            kind = rng.random()
            if kind < 0.4:
                t = str(rng.randint(1, 99))
            elif kind < 0.7:
                t = '%d*%d' % (rng.randint(1, 99), rng.randint(1, 99))
            elif kind < 0.9:
                t = '%d/%d*%d' % (rng.randint(1, 99), rng.randint(1, 9), rng.randint(1, 9))
            else:
                t = '(%d+%d)*%d' % (rng.randint(1, 99), rng.randint(1, 99), rng.randint(1, 9))
            if parts:
                sep = rng.choice([' + ', '+', ' - ', '-'])
                parts.append(sep)
                total += len(sep)
            parts.append(t)
            total += len(t)
        return ''.join(parts)

    s = long_terms(99900)
    while len(s) > 100000:
        s = long_terms(99800)
    tests.append(s)

    # deep left nesting: ((((1+2)*1+3)*1+4)...
    d = 14000
    pre = '(' * d
    suf = ''.join('+%d)' % (i % 9 + 1) for i in range(d))
    tests.append(pre + '1' + suf)

    # deep right nesting: 1-(2-(3-(...)))
    d = 11000
    parts = []
    close = 0
    for i in range(1, d + 1):
        parts.append('%d-(' % (i % 100 + 1))
        close += 1
    s = ''.join(parts) + '5' + ')' * close
    tests.append(s)

    # wide random tree
    for dep in (13, 12):
        s = rand_expr(dep, 9, False)
        if len(s) <= 100000:
            tests.append(s)
    # alternating mul/div chain with big numbers
    parts = ['2147483647']
    for i in range(4000):
        parts.append('*1/1' if i % 2 else '/1*1')
    tests.append(''.join(parts))
    return tests
